import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Configuration
  const ribbonWidth = 7.0;
  const ribbonHeight = 0.35;
  const speed = 0.4;
  const fadeWidth = 0.6;
  const fontSize = 13;
  const charWidth = 0.065;
  const tickWidth = 0.02;
  const tickHeight = 0.14;
  const tickGap = 0.5;

  // Colors
  const colors = config.visual.colors;
  const surfColor = colors.surface || '#111117';
  const accentCol = colors.accent || '#ff2a38';
  const paperCol = colors.paper || '#e8ecf2';
  const hairlineCol = '#23232b';

  // Text entries
  const entries = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18'
  ];

  // Ribbon base
  const ribbonGeom = new THREE.PlaneGeometry(ribbonWidth, ribbonHeight);
  const ribbonMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(surfColor),
    roughness: 0.6,
    metalness: 0.2,
    side: THREE.DoubleSide
  });
  const ribbonMesh = new THREE.Mesh(ribbonGeom, ribbonMat);
  ribbonMesh.position.z = 0;
  group.add(ribbonMesh);

  // Hairlines (top and bottom edges)
  const hairlineGeom = new THREE.PlaneGeometry(ribbonWidth, 0.006);
  const hairlineMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(hairlineCol),
    side: THREE.DoubleSide
  });

  const topHair = new THREE.Mesh(hairlineGeom, hairlineMat.clone());
  topHair.position.set(0, ribbonHeight / 2, 0.001);
  group.add(topHair);

  const botHair = new THREE.Mesh(hairlineGeom, hairlineMat.clone());
  botHair.position.set(0, -ribbonHeight / 2, 0.001);
  group.add(botHair);

  // Content container (will be animated)
  const contentGroup = new THREE.Group();
  group.add(contentGroup);

  // Tick mark geometry and material
  const tickGeom = new THREE.PlaneGeometry(tickWidth, tickHeight);
  const tickMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(accentCol),
    emissive: new THREE.Color(accentCol),
    emissiveIntensity: 1.5,
    side: THREE.DoubleSide
  });

  // Calculate total content width
  const totalWidth = entries.reduce((acc, text) => {
    const spacing = tickWidth + 2 * tickGap;
    return acc + text.length * charWidth + spacing;
  }, 0);

  // Layout text and ticks
  let x = -totalWidth / 2;

  entries.forEach((text, idx) => {
    // Tick mark (except before first entry)
    if (idx === 0) {
      x += tickGap;
    } else {
      const tick = new THREE.Mesh(tickGeom, tickMat.clone());
      tick.position.set(x + tickGap + tickWidth / 2, 0, 0.001);
      contentGroup.add(tick);
      x += tickGap + tickWidth + tickGap;
    }

    // Text mesh
    const textWidth = text.length * charWidth;
    if (ctx.fontAtlas && typeof ctx.fontAtlas.renderText === 'function') {
      const textMesh = ctx.fontAtlas.renderText(text, {
        fontSize,
        fontFamily: 'JetBrains Mono',
        fontWeight: 700,
        color: new THREE.Color(paperCol),
        letterSpacing: 0.06
      });

      if (textMesh) {
        textMesh.position.set(x + textWidth / 2, 0, 0.02);
        contentGroup.add(textMesh);
      }
    }

    x += textWidth + tickGap;
  });

  // Duplicate content for seamless loop
  const dupGroup = contentGroup.clone();
  dupGroup.position.x = totalWidth;
  group.add(dupGroup);

  // Edge fade texture
  const createFadeTexture = () => {
    const w = 256, h = 64;
    const data = new Uint8ClampedArray(w * h * 4);

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const idx = (y * w + x) * 4;
        let alpha = 1;

        if (x < w * 0.3) {
          alpha = x / (w * 0.3);
        } else if (x > w * 0.7) {
          alpha = (w - x) / (w * 0.3);
        }

        data[idx] = 11;
        data[idx + 1] = 11;
        data[idx + 2] = 16;
        data[idx + 3] = Math.round(alpha * 255);
      }
    }

    const texture = new THREE.DataTexture(data, w, h, THREE.RGBAFormat);
    texture.needsUpdate = true;
    return texture;
  };

  const fadeTexture = createFadeTexture();
  const fadeMat = new THREE.MeshBasicMaterial({
    map: fadeTexture,
    transparent: true,
    side: THREE.DoubleSide
  });

  const fadeGeom = new THREE.PlaneGeometry(fadeWidth, ribbonHeight);

  const leftFade = new THREE.Mesh(fadeGeom, fadeMat.clone());
  leftFade.position.set(-ribbonWidth / 2 + fadeWidth / 2, 0, 0.002);
  group.add(leftFade);

  const rightFade = new THREE.Mesh(fadeGeom, fadeMat.clone());
  rightFade.position.set(ribbonWidth / 2 - fadeWidth / 2, 0, 0.002);
  group.add(rightFade);

  // Animation timeline
  const loopDuration = totalWidth / speed;
  const timeline = gsap.timeline({ repeat: -1 });

  timeline.to(contentGroup, {
    x: -totalWidth,
    duration: loopDuration,
    ease: 'none'
  }, 0);

  timeline.to(dupGroup, {
    x: 0,
    duration: loopDuration,
    ease: 'none'
  }, 0);

  // Apply cinematic primitive
  if (ctx.primitives && ctx.primitives['fly-through']) {
    ctx.primitives['fly-through'](group, { speed: 0.4, depthUnits: 0 });
  }

  // Set position, rotation, scale
  const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };

  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  // Cleanup
  group.userData.cleanup = () => {
    timeline.kill();
    ribbonGeom.dispose();
    ribbonMat.dispose();
    hairlineGeom.dispose();
    hairlineMat.dispose();
    tickGeom.dispose();
    tickMat.dispose();
    fadeGeom.dispose();
    fadeMat.dispose();
    fadeTexture.dispose();
  };

  return group;
}
